var y = Math.max(0, +v('year') || 0), years = Math.max(1, +v('years') || 1);
var total = Math.round(y * years);
if (total < 1) { if (el._crowdStop) el._crowdStop(); el.innerHTML = ''; return; }
Crowd.units(el, { total: total, used: 0, unit: '本', leftLabel: 'これから',
title: 'これから観られる映画を玉で並べると',
final: function (l) { return 'これから観られるのは約 ' + l.toLocaleString('ja-JP') + '本。「いつか観たい」リストより、たぶん少ない数です。'; } });
